//! The CLI reference, rendered from the `clap` command tree so it cannot drift from the binary.
//!
//! `limen markdown-help` prints it; `docs/cli-reference.md` is the committed copy, and a test
//! fails when the two differ.

use std::fmt::Write as _;

use clap::{Arg, Command};

/// Render the whole command tree as Markdown. Hidden commands and arguments are left out.
pub fn render(root: &Command) -> String {
    let mut root = root.clone().disable_help_subcommand(true);
    root.build();
    let mut out = String::from(
        "<!-- Generated by `limen markdown-help`. Do not edit; run `scripts/gen-cli-reference.sh`. -->\n\n\
         # CLI reference\n\n\
         Every command and option of `limen`, generated from the binary. \
         For examples and how the commands fit together, see [the CLI guide](guides/cli.md).\n\n",
    );
    section(&mut out, &root, &[], 2);
    out
}

fn section(out: &mut String, cmd: &Command, path: &[&str], depth: usize) {
    let name = cmd.get_name();
    let mut path = path.to_vec();
    path.push(name);
    let full = path.join(" ");

    let _ = writeln!(out, "{} `{full}`\n", "#".repeat(depth.min(6)));
    if let Some(about) = cmd.get_long_about().or_else(|| cmd.get_about()) {
        let _ = writeln!(out, "{about}\n");
    }
    let mut cmd_for_usage = cmd.clone();
    let _ = writeln!(out, "```text\n{}\n```\n", cmd_for_usage.render_usage());

    let visible: Vec<&Arg> = cmd
        .get_arguments()
        .filter(|a| {
            !a.is_hide_set()
                && a.get_id() != "help"
                && a.get_id() != "version"
                // Global options are listed once, under the top-level command.
                && (path.len() == 1 || !a.is_global_set())
        })
        .collect();
    let (positional, options): (Vec<&Arg>, Vec<&Arg>) =
        visible.into_iter().partition(|a| a.is_positional());
    if !positional.is_empty() {
        out.push_str("Arguments:\n\n");
        for arg in positional {
            let _ = writeln!(
                out,
                "- `<{}>`{}",
                arg.get_id().as_str().to_uppercase(),
                describe(arg)
            );
        }
        out.push('\n');
    }
    if !options.is_empty() {
        out.push_str("Options:\n\n");
        for arg in options {
            let _ = writeln!(out, "- `{}`{}", flags(arg), describe(arg));
        }
        out.push('\n');
    }

    for sub in cmd.get_subcommands().filter(|s| !s.is_hide_set()) {
        section(out, sub, &path[..path.len()], depth + 1);
    }
}

fn flags(arg: &Arg) -> String {
    let mut parts = Vec::new();
    if let Some(short) = arg.get_short() {
        parts.push(format!("-{short}"));
    }
    if let Some(long) = arg.get_long() {
        parts.push(format!("--{long}"));
    }
    let mut text = parts.join(", ");
    if arg.get_action().takes_values() {
        let value = arg
            .get_value_names()
            .and_then(|v| v.first().map(|s| s.as_str().to_owned()))
            .unwrap_or_else(|| arg.get_id().as_str().to_uppercase());
        let _ = write!(text, " <{value}>");
    }
    text
}

fn describe(arg: &Arg) -> String {
    let mut text = String::new();
    if let Some(help) = arg.get_long_help().or_else(|| arg.get_help()) {
        let help = one_line(&help.to_string());
        let _ = write!(text, ": {help}");
        if !help.ends_with(['.', '!', '?']) {
            text.push('.');
        }
    }
    let values: Vec<String> = arg
        .get_possible_values()
        .iter()
        .filter(|v| !v.is_hide_set())
        .map(|v| v.get_name().to_owned())
        .collect();
    if !values.is_empty() {
        let _ = write!(text, " Values: {}.", values.join(", "));
    }
    let defaults: Vec<String> = arg
        .get_default_values()
        .iter()
        .map(|v| v.to_string_lossy().into_owned())
        .collect();
    if !defaults.is_empty() && arg.get_action().takes_values() {
        let _ = write!(text, " Default: `{}`.", defaults.join(", "));
    }
    if let Some(env) = arg.get_env() {
        let _ = write!(text, " Environment: `{}`.", env.to_string_lossy());
    }
    text
}

fn one_line(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

#[cfg(test)]
mod tests {
    use clap::CommandFactory;

    /// `docs/cli-reference.md` is generated; it must match the binary's command tree.
    #[test]
    fn committed_reference_is_current() {
        let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../docs/cli-reference.md");
        let generated = super::render(&crate::Cli::command());
        if std::env::var_os("UPDATE_CLI_REFERENCE").is_some() {
            std::fs::write(path, &generated).expect("write docs/cli-reference.md");
            return;
        }
        let committed = std::fs::read_to_string(path).expect("read docs/cli-reference.md");
        assert!(
            committed == generated,
            "docs/cli-reference.md is stale; regenerate it with scripts/gen-cli-reference.sh"
        );
    }
}
